from collections import deque
from typing import List

def solve(grid: List[List[int]]) -> List[List[int]]:
    """Transform the grid by recoloring connected components of 1's that form
    a hollow rectangular border (all cells on the perimeter of an axis-aligned
    rectangle are 1 and all interior cells are 0) to 3.
    """
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    out = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                # BFS to collect the component
                queue = deque()
                queue.append((r, c))
                visited[r][c] = True
                cells = [(r, c)]
                min_r = max_r = r
                min_c = max_c = c

                while queue:
                    cr, cc = queue.popleft()
                    # update bounding box
                    if cr < min_r:
                        min_r = cr
                    if cr > max_r:
                        max_r = cr
                    if cc < min_c:
                        min_c = cc
                    if cc > max_c:
                        max_c = cc

                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == 1:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                                cells.append((nr, nc))

                h = max_r - min_r + 1
                w = max_c - min_c + 1
                # A rectangle border must have height and width at least 2
                if h >= 2 and w >= 2:
                    expected_size = 2 * h + 2 * w - 4
                    if len(cells) == expected_size:
                        # Verify interior is empty (all zeros)
                        interior_empty = True
                        for rr in range(min_r + 1, max_r):
                            for cc in range(min_c + 1, max_c):
                                if grid[rr][cc] != 0:
                                    interior_empty = False
                                    break
                            if not interior_empty:
                                break
                        if interior_empty:
                            for rr, cc in cells:
                                out[rr][cc] = 3
    return out
